"use strict";

const crypto = require("crypto");

/**
 * Device locking: a webmixer client (browser) identifies itself with a random device ID
 * that it keeps in localStorage. A device can be locked to a single aux, after which the
 * server only accepts messages that change that aux's mix.
 *
 * This module is pure (no sockets, no file access) so it can be unit tested.
 */

const DEVICE_ID_PATTERN = /^[A-Za-z0-9_-]{8,64}$/;

/**
 * @param {unknown} id
 * @returns {boolean} true if id looks like a device ID generated by the web client
 */
function isValidDeviceId(id)
{
	return typeof id === "string" && DEVICE_ID_PATTERN.test(id);
}

/**
 * Extract the device ID from a websocket upgrade request URL (e.g. "/?device=abc123").
 * @param {string|undefined} url - the request url
 * @returns {string|null} the device ID, or null when it is missing or invalid
 */
function deviceIdFromUrl(url)
{
	if(!url)
	{
		return null;
	}
	let id;
	try
	{
		id = new URL(url, "http://localhost").searchParams.get("device");
	}
	catch(e)
	{
		return null;
	}
	return isValidDeviceId(id) ? id : null;
}

/**
 * @param {unknown} aux
 * @returns {boolean} true if aux is a positive integer aux number
 */
function isValidAux(aux)
{
	return Number.isInteger(aux) && aux > 0 && aux < 1000;
}

/**
 * Decide whether a device locked to an aux may send a message. This is a whitelist:
 * only send level/pan changes and queries for the locked aux (plus webmixer's own
 * group trim messages for that aux) are allowed. Everything else - other auxes,
 * channel names, anything aimed at the desk's main mix - is rejected.
 * @param {string} address - OSC address of the incoming message
 * @param {number} aux - the aux the device is locked to
 * @returns {boolean}
 */
function isAddressAllowedForAux(address, aux)
{
	if(typeof address !== "string" || !isValidAux(aux))
	{
		return false;
	}

	const send = address.match(/^\/Input_Channels\/\d{1,3}\/Aux_Send\/(\d{1,3})\/send_(?:level|pan)(?:\/\?)?$/);
	if(send)
	{
		return parseInt(send[1], 10) === aux;
	}

	const group = address.match(/^\/Webmixer\/Aux\/(\d{1,3})\/Group\/[A-Za-z0-9_-]{1,64}\/level(?:\/\?)?$/);
	if(group)
	{
		return parseInt(group[1], 10) === aux;
	}

	const layout = address.match(/^\/Webmixer\/Aux\/(\d{1,3})\/Layout$/);
	if(layout)
	{
		return parseInt(layout[1], 10) === aux;
	}

	return false;
}

/**
 * Constant time password comparison.
 * @param {string} given
 * @param {string} expected
 * @returns {boolean}
 */
function passwordMatches(given, expected)
{
	const givenBuf = Buffer.from(String(given ?? ""));
	const expectedBuf = Buffer.from(String(expected ?? ""));
	return givenBuf.length === expectedBuf.length && crypto.timingSafeEqual(givenBuf, expectedBuf);
}

/**
 * Decide whether a device may unlock itself.
 * When an admin password is configured the device must supply it, otherwise anyone may unlock.
 * @param {string|undefined} adminPassword - the configured ADMIN_PASSWORD (may be empty)
 * @param {unknown} given - the password the device sent
 * @returns {boolean}
 */
function canSelfUnlock(adminPassword, given)
{
	if(!adminPassword)
	{
		return true;
	}
	return passwordMatches(given, adminPassword);
}

module.exports = {
	isValidDeviceId,
	deviceIdFromUrl,
	isValidAux,
	isAddressAllowedForAux,
	canSelfUnlock
};
